-- 📚 꼭집 주거 사전 — 임대차 계약 기간 2년 단위 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.2초 · 결과:
-- {"anns": 200, "by_std": {"SH 고유": 2, "공공임대(6·10·50년)": 14, "국민임대": 65, "매입임대": 71, "영구임대": 25, "전세임대": 4, "행복주택": 15, "행복주택(신혼희망)": 4}, "ex": ["SH_311349", "SH_311087", "SH_310653", "SH_310650"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where t~'(임대차\s*계약\s*기간|임대기간)[^.]{0,20}2\s*년'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where t~'(임대차\s*계약\s*기간|임대기간)[^.]{0,20}2\s*년' group by 1)q),'ex',(select json_agg(i) from(select distinct announcement_id i from y where t~'(임대차\s*계약\s*기간|임대기간)[^.]{0,20}2\s*년' order by 1 desc limit 4)q))j;
